import {uuid,money,paise,initialState,session,unitPrice,makeLine,totals,createOrder,markPaid,correctOrder,addGame,voidGame,report,stockUsed,netFor,audit,refreshMilestones,validateBackup,integer} from './domain.mjs';
import {init,mutate,read,onExternalChange} from './storage.mjs';
import {icon,food} from './art.mjs';
let state,screen='sell',category='All',orderFilter='All',search='',promo=false,adminUntil=0,busy=false,sheetKind='',installPrompt=null,afterPin=null;
const app=document.querySelector('#app'),sheet=document.querySelector('#sheet');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S=()=>state[state.mode],C=()=>state.config;
const date=x=>new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(x));
const orderNo=o=>`#${String(o.number).padStart(3,'0')}`;
const btn=(label,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const select=(label,name,options,value)=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;
const check=(name,label,checked=false)=>`<label class="check-label"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200);}
function error(e){const el=sheet.querySelector('[data-error]');if(el){el.textContent=e.message||String(e);el.hidden=false;}else toast(e.message||'Something went wrong. Your saved records are unchanged.');}
async function commit(fn){const result=await mutate(fn);state=result.state;return result.output;}
function brand(){return `<div class="brand"><span class="packet">PACKET</span><span class="pataka">PATAKA</span><small>STALL NO. ${esc(C().stallNumber)}</small></div>`;}
const navItems=[['sell','Sell'],['dashboard','Dashboard'],['orders','Orders'],['milestones','Milestones'],['more','More']];
function nav(mobile=false){return `<nav class="${mobile?'bottom-nav':'side-nav'}" aria-label="${mobile?'Mobile':'Main'} navigation">${navItems.map(([key,label])=>btn(`${icon(key)}<span>${label}</span>`,'nav',`nav-button ${screen===key||screen==='games'&&key==='more'?'active':''}`,`data-screen="${key}" aria-current="${screen===key?'page':'false'}"`)).join('')}</nav>`;}
function render(){if(!state)return;document.documentElement.style.setProperty('--yellow',C().accent||'#ffdd35');const r=report(S(),C());app.innerHTML=`${state.mode==='demo'?`<div class="demo-bar">PRACTICE MODE · Demo records stay separate from your live event.${btn('Back to live','mode-live','')}</div>`:''}<div class="app-shell"><aside class="sidebar">${brand()}${nav()}<div class="side-bottom"><div class="stall-note">${icon('bolt')}<h3>Little packets.<br>Big pataka energy.</h3><p>4 NOVEMBER 2026<br>DIWALI CELEBRATION · JABALPUR</p></div><div class="device"><span class="device-dot"></span><div><strong>Saved on this device</strong><br>Single-checkout-device mode</div></div></div></aside><div class="workspace"><header class="topbar"><div class="event-info"><div class="event-title">${esc(C().stallName.toUpperCase())} · SALES COMMAND CENTER</div><div class="event-sub">Baderia Global Institute · ${esc(C().eventDate)} · Stall ${esc(C().stallNumber)}</div></div><div class="mobile-brand">${brand()}</div><div class="top-right"><span class="status-pill"><span class="status-dot" style="background:${navigator.onLine?'#50982f':'#cc812b'}"></span>${navigator.onLine?'ONLINE':'OFFLINE'} · DEVICE ONLY</span><span class="operator-name muted" style="font-size:11px">${esc(C().operator)}</span>${btn('PP','operator','avatar','aria-label="Change operator"')}</div></header><main class="main" id="main">${({sell:sellScreen,dashboard:dashboardScreen,orders:ordersScreen,milestones:milestonesScreen,more:moreScreen,games:gamesScreen}[screen]||sellScreen)(r)}</main></div></div>${nav(true)}${screen==='sell'?mobileCart():''}`;}
function heading(title,subtitle,right=''){return `<div class="screen-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${right}</div>`;}
function miniMission(r){return `<div class="mini-mission"><div class="target-icon">${icon('target')}</div><div class="grow"><h3>${r.remaining?'THE '+money(C().target)+' MISSION':'MISSION COMPLETE!'}</h3><div class="mission-numbers"><strong>${money(r.collected)}</strong> / ${money(C().target)} recovered</div></div><div class="row"><div class="mini-progress" role="progressbar" aria-label="Investment recovered" aria-valuenow="${r.percent.toFixed(1)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${r.percent}%"></div></div><strong class="percent" style="font-size:11px">${r.percent.toFixed(0)}%</strong></div>${btn(`View mission ${icon('arrow')}`,'nav','quiet','data-screen="dashboard"')}</div>`;}
function menuReadiness(){const active=C().products.filter(p=>p.active);return {active,ready:active.filter(p=>unitPrice(p,C())!==null).length};}
function sellScreen(r){const products=C().products.filter(p=>p.active&&(category==='All'||p.category===category));const readiness=menuReadiness();return `${heading('Let’s make some noise.','Good food. Fast orders. A fest to remember.',`<span class="badge ${readiness.ready===readiness.active.length?'lime':'pink'}">${icon(readiness.ready===readiness.active.length?'check':'lock')} ${readiness.ready}/${readiness.active.length} PRICED</span>`)}${miniMission(r)}${readiness.ready!==readiness.active.length?`<div class="menu-locked-banner">${icon('lock')}<div class="grow"><strong>Stall setup mode</strong><p>Prices are hidden and every item stays locked until you set it at the stall.</p></div>${btn('Set prices','admin-menu','small')}</div>`:''}${state.mode==='demo'&&!S().orders.length?`<div class="notice" style="margin-bottom:20px">Try practice orders once prices are set. Live sales stay untouched.</div>`:''}<div class="sell-layout"><section class="catalog" aria-label="Product menu"><div class="categories" role="group" aria-label="Product categories">${['All','Crispy Dhamaka','Pizza Pataka','Fizz Pataka','Combo Pataka','Games'].map(cat=>btn(cat==='All'?'All items':cat,cat==='Games'?'games':'category',cat===category?'active':'',`data-category="${cat}"`)).join('')}</div><div class="menu-caption"><span>${category==='All'?'TODAY’S COMPLETE MENU':category.toUpperCase()}</span><span>${products.length} ITEMS</span></div><div class="products">${products.map(productCard).join('')}</div><div class="catalog-footer">${icon('check')} Pick the item. Set the price. Serve the pataka.</div></section>${cartPanel()}</div>`;}
function productCard(p){const price=unitPrice(p,C());const qty=S().draft.filter(l=>l.productId===p.id).reduce((s,l)=>s+l.quantity,0);const used=stockUsed(S());const remaining=p.stockKey?(C().stock[p.stockKey]||0)-(used[p.stockKey]||0):null;const sold=p.soldOut||(p.base&&C().products.find(x=>x.id===p.base)?.soldOut)||C().inventory&&remaining!==null&&remaining<(p.stockUnits||1);const locked=price===null;return `<button class="product-card ${esc(p.tint)} ${locked?'price-locked':''}" data-action="product" data-id="${esc(p.id)}" ${locked||sold?'disabled':''} aria-label="${esc(p.name)}, ${locked?'price locked':money(price)}, ${p.custom?'customize':'add to order'}"><div class="product-art"><span class="product-tag">${locked?'STALL PRICE LOCKED':p.bundle?'COMBO READY':p.category.toUpperCase()}</span>${qty?`<span class="qty-badge">${qty}</span>`:''}${food(p.art)}</div><div class="product-info"><h3>${esc(p.name)}</h3><small>${sold?'Sold out':C().inventory&&remaining!==null?`${remaining} in stock`:p.bundle?'Built as a single combo price.':p.category==='Fizz Pataka'?'Chilled and ready to go.':p.category==='Pizza Pataka'?'Fresh Pizza Pataka.':'Crispy Dhamaka, made your way.'}</small><div class="product-bottom">${locked?'<span class="setup-label">Price locked at stall</span>':`<strong class="price">${money(price)}</strong>`}<span class="add-circle">${icon(locked?'lock':'plus')}</span></div></div></button>`;}
function cartLines(){return S().draft.map(l=>`<div class="cart-line"><div><h3>${esc(l.name)}</h3><p>${[l.size,l.flavour,...l.addons.map(a=>a.name)].filter(Boolean).map(esc).join(' · ')||'Fresh from stall no. 10'}</p><div class="stepper">${btn(icon('minus'),'qty','',`data-id="${l.id}" data-delta="-1" aria-label="Decrease ${esc(l.name)} quantity"`)}<span>${l.quantity}</span>${btn(icon('plus'),'qty','',`data-id="${l.id}" data-delta="1" aria-label="Increase ${esc(l.name)} quantity"`)}</div></div><div style="text-align:right"><strong>${money(l.unitPrice*l.quantity)}</strong><br>${btn(icon('close'),'remove','quiet icon-btn',`data-id="${l.id}" aria-label="Remove ${esc(l.name)}"`)}</div></div>`).join('');}
function cartFooter(){const t=totals(S().draft,C(),promo);return `<div class="cart-footer">${btn(`${icon('spark')} Reel / banner? ${money(C().promo)} off`,'promo',`promo-button ${promo?'active':''}`)}<div class="row between" style="margin-top:17px"><span class="muted">Subtotal</span><strong>${money(t.subtotal)}</strong></div>${t.discount?`<div class="row between"><span>Promo discount</span><strong>−${money(t.discount)}</strong></div>`:''}<div class="row between total"><span>Order total</span><span class="price">${money(t.total)}</span></div>${btn(`Review & pay ${icon('arrow')}`,'checkout','primary',S().draft.length?'':'disabled')}<p class="hint">${icon('lock')} Saved locally. Ready when you are.</p></div>`;}
function cartPanel(){return `<aside class="cart-panel" aria-label="Current order"><div class="cart-head"><h2>Your order</h2><span class="badge">${S().draft.reduce((n,l)=>n+l.quantity,0)} ITEMS</span></div><div class="cart-body">${S().draft.length?cartLines():`<div class="empty-cart"><div class="empty-icon">${icon('cart')}</div><h3>Good things start here.</h3><p>Tap a little something from the menu to start your next order.</p></div>`}</div>${cartFooter()}</aside>`;}
function mobileCart(){const count=S().draft.reduce((n,l)=>n+l.quantity,0);return `<div class="mobile-cart">${count?btn(`${icon('cart')}<span><small>${count} items</small><strong class="price">${money(totals(S().draft,C(),promo).total)}</strong></span>`,'view-cart','quiet'): `<span class="empty-mobile">${icon('cart')} Your next order starts here</span>`}${btn(`Review & pay ${icon('arrow')}`,'checkout','primary',count?'':'disabled')}</div>`;}
function missionHero(r){return `<section class="panel mission-hero"><div class="row between"><div><div class="eyebrow">THE PACKET PATAKA MISSION</div><h2>${r.remaining?'LET’S GET OUR INVESTMENT BACK.':'THE BIG PATAKA. MISSION COMPLETE!'}</h2></div>${icon('target')}</div><div class="mission-inner"><span class="big-number">${money(r.collected)}</span> <span class="target">/ ${money(C().target)}</span><div class="progress" role="progressbar" aria-label="Recovery target" aria-valuenow="${r.percent.toFixed(1)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${r.percent}%"></div></div><div class="row between"><strong>${r.percent.toFixed(1)}% recovered</strong><span class="badge ${r.remaining?'pink':'lime'}">${r.remaining?money(r.remaining)+' to go':money(r.above)+' Above Recovery Target'}</span></div></div></section>`;}
function dashboardScreen(r){const stats=[['cash',money(r.collected),'Recorded collected revenue'],['orders',r.orders,'Orders completed'],['sell',r.units,'Items sold · bundles count as one'],['dashboard',money(r.average),'Average food order'],['cash',money(r.methods.Cash),'Cash collected · net'],['upi',money(r.methods.UPI),'UPI collected · net'],['spark',money(r.discounts),'Promo discounts given'],['game',r.games,'Games played']];return `${heading('Every packet counts.','Your real-time view of the stall, powered by saved sales.',btn(`${icon('download')} Export`,'export-csv','small'))}${missionHero(r)}<div class="stats">${stats.map(([i,v,l])=>`<div class="panel stat">${icon(i)}<strong>${v}</strong><p>${l}</p></div>`).join('')}</div><div class="grid-2"><section class="panel"><div class="panel-title"><h2>${icon('milestones')} Today’s bestsellers</h2><span class="badge">BY UNITS</span></div>${r.best.length?r.best.slice(0,5).map((p,i)=>`<div class="list-row"><span class="rank">${i+1}</span><div class="grow"><h3>${esc(p.name)}</h3></div><span class="badge">${p.units} sold</span></div>`).join(''):'<div class="empty-state">Your first sale will get the leaderboard going.</div>'}</section><section class="panel"><div class="panel-title"><h2>Fresh off the counter</h2>${btn('View all →','nav','quiet small','data-screen="orders"')}</div>${S().orders.length?S().orders.slice(-5).reverse().map(orderRow).join(''):'<div class="empty-state">No orders yet. Let’s make the first one a pataka.</div>'}</section><section class="panel"><div class="panel-title"><h2>Where the money came from</h2></div>${bars(r.methods)}<div class="separator"></div><div class="row between" style="font-size:12px"><span>Game income included</span><strong>${money(r.gameIncome)}</strong></div><p class="footnote">Payments are manually confirmed by your team. Refunds are deducted from the original payment method.</p></section><section class="panel"><div class="panel-title"><h2>Menu mix</h2><span class="badge">GROSS ITEM VALUE</span></div>${Object.keys(r.categories).length?bars(r.categories):'<p class="empty-state">Your sales mix will appear here.</p>'}</section><section class="panel"><div class="panel-title"><h2>Hourly collections</h2><span class="badge">IST · NET</span></div>${Object.keys(r.hourly).length?bars(Object.fromEntries(Object.entries(r.hourly).sort().map(([h,v])=>[`${h}:00`,v]))):'<p class="empty-state">No collections recorded yet.</p>'}</section><section class="panel"><div class="panel-title"><h2>The honest numbers</h2></div>${[['Gross food sales',r.gross],['Promo discounts',r.discounts],['Refunds & reversals',r.refunds],['Net food collections',r.food],['Recorded expenses',r.expenses],['Collections less recorded expenses',r.collected-r.expenses]].map(([k,v])=>`<div class="receipt-line"><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}<p class="footnote">Recovery is measured against ${money(C().target)}. The expense balance is not accounting profit unless all costs have been recorded. The investment is not automatically deducted again.</p></section></div>`;}
function bars(values){const max=Math.max(1,...Object.values(values));return Object.entries(values).map(([k,v])=>`<div class="bar-row"><div class="row between"><span>${esc(k)}</span><strong>${money(v)}</strong></div><div class="bar-track"><span style="width:${Math.max(0,v/max*100)}%"></span></div></div>`).join('');}
function orderRow(o){return `<button class="order-row" data-action="receipt" data-id="${o.id}"><span class="receipt-icon">${icon('orders')}</span><div class="grow"><h3>Order ${orderNo(o)}</h3><p>${date(o.at)} · ${esc(o.method)}</p></div><div class="order-right"><strong class="price">${money(o.total)}</strong><span class="badge ${o.status==='paid'?'lime':'pink'}">${o.status.toUpperCase()}</span></div></button>`;}
function ordersScreen(){const list=S().orders.filter(o=>(orderFilter==='All'||orderFilter==='Pending'&&o.status==='pending'||orderFilter==='Refunded / Void'&&['partial','refunded','void'].includes(o.status)||o.method===orderFilter)&&(!search||orderNo(o).includes(search)||o.id.includes(search))).slice().reverse();return `${heading('The paper trail.','Every order. Every rupee. All accounted for.',`<input class="search-input" aria-label="Search order number" id="order-search" placeholder="Search #order" value="${esc(search)}">`)}<div class="filters">${['All','Cash','UPI','Other','Pending','Refunded / Void'].map(f=>btn(f,'filter',f===orderFilter?'active':'',`data-filter="${f}"`)).join('')}</div><section class="panel">${list.length?list.map(orderRow).join(''):`<div class="empty-state">${icon('orders')}<h3>No orders here yet.</h3><p>Completed and pending orders will appear here.</p></div>`}</section>`;}
const milestoneInfo=[['spark','FIRST SPARK','Complete your first paid sale.','bolt'],['game','GAME ON','Welcome the first game participant.','game'],['crowd','CROWD MAGNET','50 orders served. A whole lot of happy cravings.','milestones'],['big','THE BIG PATAKA','Recover the event investment.','target']];
function milestonesScreen(r){return `${heading('Small sparks. Big wins.','A little motivation for the team behind the magic.',`<span class="badge lime">${Object.values(S().milestones).filter(m=>m.active).length} / 4 UNLOCKED</span>`)}${miniMission(r)}<div class="grid-2">${milestoneInfo.map(([id,title,desc,i])=>{const m=S().milestones[id];const value=id==='spark'?Math.min(r.orders,1):id==='game'?Math.min(r.games,1):id==='crowd'?Math.min(r.orders,50):r.percent;const goal=id==='crowd'?50:id==='big'?100:1;return `<section class="panel milestone-card ${m?.active?'unlocked':''}"><div class="milestone-symbol">${icon(m?.active?'check':i)}</div><div class="grow"><div class="eyebrow" style="margin-bottom:7px">${m?.active?'UNLOCKED':m?.unlockedAt?'REVERSED · KEEP GOING':'YOUR NEXT SPARK'}</div><h3>${title}</h3><p>${desc}</p><div class="bar-track" style="margin-top:12px"><span style="background:${m?.active?'#83c84c':'#ffdd35'};width:${value/goal*100}%"></span></div><small>${m?.active?'Unlocked '+date(m.unlockedAt):id==='big'?money(r.remaining)+' to go':value+' / '+goal+(id==='crowd'?' orders':'')}</small></div></section>`;}).join('')}</div><p class="footnote">Achievements follow valid paid orders and recorded games. Refunds and reversals can deactivate a milestone; the original unlock time stays in the audit history. Orders are a proxy for service volume, not unique people.</p>`;}
function moreScreen(){const readiness=menuReadiness();const tiles=[['settings','Set stall prices',`${readiness.ready}/${readiness.active.length} menu items ready`,'admin-menu'],['bolt','Event setup','Review price locks before live selling.','event-setup'],['game','The game corner','Record physical games and prize handouts.','games'],['sell','Stock room','Optional stock counts. No ingredient spreadsheets.','admin-stock'],['cash','Expenses','Keep track of extra supplies and event costs.','expenses'],['settings','Stall settings','Your target, promo offer, operators and event.','admin-settings'],['download','Backup & exports','Download CSV, save JSON or restore a backup.','backups'],['spark','Practice counter','Try a separate demo ledger before the rush.','mode-demo'],['lock','Admin access','Set or change the local admin PIN.','admin-pin']];return `${heading('Behind the counter.','Everything you need, arranged for a busy stall.') }<div class="notice" style="margin-bottom:22px"><strong>One checkout device. One reliable ledger.</strong><br>Sales stay in this browser. Other phones do not share these totals. Export backups regularly; clearing browser data can remove your records.</div><div class="settings-grid">${tiles.map(([i,t,d,a])=>btn(`${icon(i)}<h3>${t}</h3><p>${d}</p>`,a,'settings-tile')).join('')}</div><div class="row wrap" style="margin-top:24px">${btn(`${icon('download')} Install app`,'install','yellow')}${btn(`${icon('lock')} Request persistent storage`,'persist','')}${adminUntil>Date.now()?btn('Lock admin','lock-admin',''):''}</div><p class="footnote">Cashier: ${esc(C().operator)} · INR (₹) · Asia/Kolkata<br>The local PIN is a shared-device guard, not cloud authentication. Exported backups contain your sales and settings.</p>`;}
function gamesScreen(r){return `${heading('Bring on the game face.','The games happen at the stall. We’ll keep the score.',btn('← More','nav','small','data-screen="more"'))}<div class="grid-2">${C().games.map(g=>`<section class="panel game-card"><span class="game-count">${S().games.filter(x=>x.gameId===g.id&&!x.void).length}</span>${icon(g.id==='wheel'?'target':'game')}<h2>${esc(g.name)}</h2><p>${g.fee?money(g.fee)+' entry fee':'Free to play'} · Real-world game</p>${btn(`${icon('plus')} Record participation`,'game-sheet','',`data-id="${g.id}"`)}</section>`).join('')}</div><div class="stats"><div class="panel stat"><strong>${r.games}</strong><p>Plays recorded · not unique people</p></div><div class="panel stat"><strong>${money(r.gameIncome)}</strong><p>Net game collections</p></div></div><section class="panel"><div class="panel-title"><h2>Recent plays</h2></div>${S().games.length?S().games.slice(-20).reverse().map(g=>`<div class="list-row"><div class="grow"><h3>${esc(g.name)} ${g.void?'· REVERSED':''}</h3><p>${date(g.at)} · ${esc(g.operator)}${g.prize?' · Prize: '+esc(g.prize):''}</p></div><strong>${money(g.fee)}</strong>${!g.void?btn('Reverse','game-reverse','small',`data-id="${g.id}"`):''}</div>`).join(''):'<p class="empty-state">Who’s feeling lucky? Record the first play.</p>'}</section>`;}
function openSheet(title,body,actions='',kind=''){sheetKind=kind;sheet.innerHTML=`<div class="sheet-head"><h2>${title}</h2>${btn(icon('close'),'close','quiet icon-btn','aria-label="Close panel"')}</div><div class="sheet-body"><div class="form-error" data-error hidden role="alert"></div>${body}</div>${actions?`<div class="sheet-actions">${actions}</div>`:''}`;if(!sheet.open)sheet.showModal();sheet.scrollTop=0;}
function closeSheet(){sheet.close();sheetKind='';}
function showCart(){openSheet('Your order',S().draft.length?cartLines():'<p>Your cart is empty.</p>',btn('Keep adding','close','')+btn('Review & pay →','checkout','primary',S().draft.length?'':'disabled'),'cart');}
function customize(id){const p=C().products.find(p=>p.id===id);openSheet('Make it your pataka.',`<form id="custom-form" data-product="${id}"><div class="sheet-product">${food(p.art)}<div><h3>${esc(p.name)}</h3><p>Veggies & standard sauces included</p><strong id="custom-price">${money(p.price)}</strong></div></div>${select('Packet size','size',[['small','Small · '+money(C().products.find(p=>p.id==='small').price)],['large','Large · '+money(C().products.find(p=>p.id==='large').price)]],p.size)}${select('Pick your packet','flavour',C().flavours,C().flavours[0])}<div class="field"><span class="field-label">Make it extra · optional add-ons</span><div class="addon-grid">${C().addons.map(a=>`<label class="choice"><input type="checkbox" name="addons" value="${a.id}"><span>${esc(a.name)}</span><strong>+${money(a.price)}</strong></label>`).join('')}</div></div><div class="row between"><span class="field-label">Quantity</span><div class="stepper">${btn(icon('minus'),'custom-qty','','type="button" data-delta="-1" aria-label="Decrease quantity"')}<span id="custom-qty">1</span>${btn(icon('plus'),'custom-qty','','type="button" data-delta="1" aria-label="Increase quantity"')}</div></div></form>`,btn('Add to order →','add-custom','primary'),'custom');}
function customValue(){const f=document.querySelector('#custom-form'),data=new FormData(f);return {id:data.get('size'),quantity:Number(document.querySelector('#custom-qty').textContent),flavour:data.get('flavour'),addons:data.getAll('addons')};}
function customPrice(){const v=customValue();document.querySelector('#custom-price').textContent=money(makeLine(C(),v.id,v).lineTotal);}
async function addLine(line){await commit(st=>{const d=st[st.mode].draft;const key=l=>JSON.stringify([l.productId,l.unitPrice,l.flavour,l.addons.map(a=>a.id).sort()]);const existing=d.find(l=>key(l)===key(line));if(existing){integer(existing.quantity+line.quantity,1);if(existing.quantity+line.quantity>999)throw Error('Maximum quantity is 999.');existing.quantity+=line.quantity;existing.lineTotal=existing.unitPrice*existing.quantity;}else d.push(line);});render();toast(`${line.name} added. Let’s go!`);}
function checkout(){if(!S().draft.length)return;const t=totals(S().draft,C(),promo);openSheet('Good food. Let’s get paid.',`<form id="checkout-form" data-signature="${esc(JSON.stringify(S().draft))}"><div class="stack">${S().draft.map(l=>`<div class="receipt-line"><span>${l.quantity} × ${esc(l.name)}<small>${[l.flavour,...l.addons.map(a=>a.name)].filter(Boolean).map(esc).join(' · ')}</small></span><strong>${money(l.unitPrice*l.quantity)}</strong></div>`).join('')}</div><div style="margin-top:18px">${btn(`${icon('spark')} Promo reel / banner · ${money(C().promo)} off`,'checkout-promo',`promo-button ${promo?'active':''}`,'type="button"')}</div>${C().promoMinimum?`<p class="footnote">Minimum order ${money(C().promoMinimum)}.</p>`:''}<div class="receipt-line"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div><div class="receipt-line"><span>Discount</span><strong>−${money(t.discount)}</strong></div><div class="row between" style="margin:20px 0"><h3>Total to collect</h3><span class="checkout-total">${money(t.total)}</span></div><div class="field"><span class="field-label">Payment method</span><div class="choices">${['Cash','UPI','Other'].map((m,i)=>`<label class="choice"><input type="radio" name="method" value="${m}" ${i===0?'checked':''}>${icon(m==='UPI'?'upi':'cash')}${m}</label>`).join('')}</div></div><div id="cash-fields">${field('Cash received · optional','cashReceived','','text','inputmode="decimal" placeholder="e.g. 200"')}<p id="cash-change" class="footnote"></p></div><div id="payment-confirmation" hidden>${check('confirmed','I checked the external app / payment and received the money.')}<p class="footnote">Selecting UPI does not verify a bank transaction.</p></div>${check('pending','Save as pending · no payment received yet')}</form>`,btn('Edit order','view-cart','')+btn(`Complete sale · ${money(t.total)}`,'complete','primary'),'checkout');}
function checkoutFields(){const f=document.querySelector('#checkout-form');if(!f)return;const d=new FormData(f),method=d.get('method'),pending=d.has('pending');document.querySelector('#cash-fields').hidden=method!=='Cash'||pending;document.querySelector('#payment-confirmation').hidden=method==='Cash'||pending;const button=sheet.querySelector('[data-action="complete"]');button.textContent=pending?'Save pending order':`Complete sale · ${money(totals(S().draft,C(),promo).total)}`;const val=d.get('cashReceived');try{document.querySelector('#cash-change').textContent=val?`Change to return: ${money(Math.max(0,paise(val)-totals(S().draft,C(),promo).total))}`:'';}catch{document.querySelector('#cash-change').textContent='Enter a valid cash amount.';}}
async function complete(){if(busy)return;const d=new FormData(document.querySelector('#checkout-form')),method=d.get('method'),pending=d.has('pending');if(!pending&&method!=='Cash'&&!d.has('confirmed'))throw Error('Confirm receipt of the payment, or save this order as pending.');const cashReceived=!pending&&method==='Cash'&&d.get('cashReceived')?paise(d.get('cashReceived')):null;busy=true;const button=sheet.querySelector('[data-action="complete"]');button.disabled=true;button.textContent='Saving…';const id=S().draftId;const signature=document.querySelector('#checkout-form').dataset.signature;try{const o=await commit(st=>{if(!st[st.mode].orders.some(o=>o.id===id)&&JSON.stringify(st[st.mode].draft)!==signature)throw Error('The cart changed in another tab. Close this panel and review the current order.');return createOrder(st[st.mode],st.config,{id,items:st[st.mode].draft,promo,method,pending,cashReceived});});promo=false;closeSheet();render();toast(`ORDER ${orderNo(o)} ${pending?'SAVED PENDING':'COMPLETED'} · ${money(o.total)}`);}finally{busy=false;if(sheet.open)checkoutFields();button.disabled=false;}}
function receipt(id){const o=S().orders.find(o=>o.id===id);openSheet(`Order ${orderNo(o)}`,`<div class="row between"><span class="badge ${o.status==='paid'?'lime':'pink'}">${o.status.toUpperCase()}</span><strong>${esc(o.method)}</strong></div><p class="footnote">${date(o.at)} · ${esc(o.operator)}<br>Reference: ${esc(o.id)}</p><div class="separator"></div>${o.items.map(l=>`<div class="receipt-line"><span>${l.quantity} × ${esc(l.name)}<small>${[l.size,l.flavour,...l.addons.map(a=>a.name)].filter(Boolean).map(esc).join(' · ')}<br>${money(l.unitPrice)} each${l.bundle?' · bundle priced once':''}</small></span><strong>${money(l.lineTotal)}</strong></div>`).join('')}${[['Subtotal',o.subtotal],['Promo discount',-o.discount],['Order total',o.total],['Net collected',netFor(S(),id)],...(o.cashReceived!==null?[['Cash received',o.cashReceived],['Change returned',o.change]]:[])].map(([k,v])=>`<div class="receipt-line"><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}<h3 style="margin-top:24px">Correction & payment history</h3>${S().audit.filter(a=>a.entityId===id).map(a=>`<div class="audit-line"><strong>${esc(a.type.replaceAll('-',' '))}</strong> · ${date(a.at)}<br>${esc(a.operator)}${a.details.reason?' · '+esc(a.details.reason):''}${a.details.amount!==undefined?' · '+money(a.details.amount):''}</div>`).join('')}`,`${o.status==='pending'?btn('Confirm payment','pending-payment','primary',`data-id="${id}"`):''}${!['void','refunded'].includes(o.status)?btn('Correct order','correction','',`data-id="${id}"`):''}`,'receipt');}
function paymentSheet(id){const o=S().orders.find(o=>o.id===id);openSheet('Confirm pending payment',`<form id="pending-form" data-id="${id}"><p class="notice">Order ${orderNo(o)} · Collect ${money(o.total)} once.</p><div style="margin-top:18px">${select('Payment received through','method',['Cash','UPI','Other'],o.method)}</div>${check('confirmed','I have received this payment and verified it externally where needed.')}</form>`,btn('Mark paid','mark-paid','primary'),'pending');}
function correctionSheet(id){const o=S().orders.find(o=>o.id===id);openSheet(`Correct order ${orderNo(o)}`,`<form id="correction-form" data-id="${id}"><p class="notice">Corrections are permanent audit entries. A refund reduces recorded collections. Voiding also releases reserved inventory. Refunded food does not return to stock.</p><div style="margin-top:18px">${select('Action','type',o.status==='pending'?[['void','Void unpaid order']]:[['refund','Refund amount'],['void','Void entire order']],o.status==='pending'?'void':'refund')}</div>${field('Refund amount · ₹','amount',netFor(S(),id)/100,'text','inputmode="decimal"')}${field('Reason · required','reason','','text','required maxlength="200"')}${check('confirmed','I confirm this correction and have returned any money owed.')}</form>`,btn('Confirm correction','save-correction','danger'),'correction');}
function gameSheet(id){const g=C().games.find(g=>g.id===id);openSheet(esc(g.name),`<form id="game-form" data-id="${id}" data-key="${uuid()}"><div class="notice">${g.fee?`Collect ${money(g.fee)} for this play.`:'This game is free. No income will be recorded.'} Food order counts stay unchanged.</div><div style="margin-top:18px">${field('Prize awarded · optional','prize','','text','maxlength="120"')}${g.fee?select('Payment method','method',['Cash','UPI','Other'],'Cash')+check('confirmed','I confirm the entry fee has been received.'):''}</div></form>`,btn('Record this play','save-game','primary'),'game');}
async function hashPin(pin,salt){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+':'+pin));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
function requireAdmin(fn){if(Date.now()<adminUntil){fn();return;}afterPin=fn;openSheet(state.pin?'Admin access':'Set your admin PIN',`<form id="pin-form"><p class="notice">${state.pin?'Unlock menu changes and corrections for 10 minutes.':'Choose a 4–8 digit PIN to guard settings and corrections on this device.'} This is not a cloud account.</p><div style="margin-top:18px">${field(state.pin?'Admin PIN':'New PIN','pin','','password','inputmode="numeric" pattern="[0-9]{4,8}" maxlength="8" autocomplete="off"')}${!state.pin?field('Repeat PIN','repeat','','password','inputmode="numeric" maxlength="8" autocomplete="off"'):''}</div></form>`,btn(state.pin?'Unlock admin':'Save PIN & continue','unlock','primary'),'pin');}
function adminMenu(){const readiness=menuReadiness();openSheet('Set stall prices',`<div class="notice"><strong>${readiness.ready}/${readiness.active.length} ready to sell.</strong><br>Every menu item starts locked. Add only the prices you decide at the stall; blank items stay unavailable to cashiers.</div>${C().products.map(p=>`<div class="admin-row"><div class="grow"><h3>${esc(p.name)}</h3><small>${esc(p.category)} · ${p.active?'Visible':'Hidden'}${p.soldOut?' · Sold out':''}</small></div><strong class="price">${unitPrice(p,C())===null?'LOCKED':money(unitPrice(p,C()))}</strong>${btn(unitPrice(p,C())===null?'Set price':'Edit','edit-product','small',`data-id="${p.id}"`)}</div>`).join('')}<div class="row wrap" style="margin-top:18px">${btn('Add product','new-product','yellow')}${btn('Manage extras','edit-addons','')}${btn('New combo','new-combo','')}</div>`,btn('Done','close',''),'admin-menu');}
function productEditor(id){const p=id?C().products.find(p=>p.id===id):{id:uuid(),name:'',category:'Fizz Pataka',price:null,art:'cold',tint:'cream',active:true,stockUnits:1};const isNew=!id;const base=!!p.base;const bundle=!!p.bundle;openSheet(bundle?'Set combo price':isNew?'Add a menu item':'Set '+esc(p.name),`<form id="product-form" data-id="${p.id}" data-new="${isNew}">${field('Product name','name',p.name,'text','required maxlength="50"')}${select('Menu group','category',['Crispy Dhamaka','Pizza Pataka','Fizz Pataka','Combo Pataka'],p.category)}${base?`<div class="notice">Price follows ${esc(C().products.find(x=>x.id===p.base)?.name)} plus selected extras.</div>${select('Base item','base',C().products.filter(x=>x.stockKey&&!x.base&&!x.bundle).map(x=>[x.id,x.name]),p.base)}<div class="field" style="margin-top:15px"><span class="field-label">Preset extras</span><div class="addon-grid">${C().addons.map(a=>`<label class="choice"><input type="checkbox" name="addons" value="${a.id}" ${p.addons.includes(a.id)?'checked':''}>${esc(a.name)}</label>`).join('')}</div></div>`:field('Selling price · ₹ (leave blank to keep locked)','price',p.price===null?'':p.price/100,'text','inputmode="decimal"')}${bundle?`<div class="field"><span class="field-label">Included items · units per combo</span>${C().products.filter(x=>x.stockKey&&!x.base&&!x.bundle).map(x=>field(esc(x.name),'bundle-'+x.id,p.bundle.find(b=>b.productId===x.id)?.quantity||0,'number','min="0" max="99"')).join('')}<small>This is one combo price. Component prices are never added again.</small></div>`:select('Stock pool','stockKey',[['','Untracked'],...Object.keys(C().stock)],p.stockKey||'')+field('Stock units consumed per item','stockUnits',p.stockUnits||1,'number','min="1" max="99"')}${select('Illustration','art',['packet','corn','pizza','lemon','masala','cold'],p.art)}${check('active','Show on menu',p.active)}${check('soldOut','Mark as sold out',p.soldOut)}</form>`,btn('Save menu item','save-product','primary'),'product-edit');}
function addonsEditor(){openSheet('Add-ons & packet flavours',`<form id="addons-form">${C().addons.map(a=>`<div class="form-grid">${field('Add-on name','name-'+a.id,a.name,'text','required maxlength="40"')}${field('Price · ₹','price-'+a.id,a.price/100,'text','inputmode="decimal"')}</div>`).join('')}<div class="separator"></div><h3 style="margin-bottom:15px">Add a premium topping</h3><div class="form-grid">${field('New topping · optional','newName','','text','maxlength="40"')}${field('Price · ₹','newPrice','','text','inputmode="decimal"')}</div><div class="field"><label for="flavours">Packet flavours · one per line</label><textarea id="flavours" name="flavours" rows="8">${esc(C().flavours.join('\n'))}</textarea><small>Basic vegetables and standard sauces are included. Mayonnaise is not charged unless you add it here.</small></div></form>`,btn('Save add-ons & flavours','save-addons','primary'),'addons');}
function stockEditor(){const used=stockUsed(S());openSheet('The stock room',`<form id="stock-form">${check('inventory','Enable stock tracking',C().inventory)}<p class="notice">Enter total available stock including already-used units. Pending orders reserve stock. Presets draw from their packet size; a topping never consumes a second packet.</p><div class="form-grid" style="margin-top:20px">${Object.entries(C().stock).map(([key,n])=>field(`${esc(key)} · ${used[key]||0} used`,'stock-'+key,n,'number',`min="${used[key]||0}" max="100000"`)).join('')}</div></form>`,btn('Save inventory','save-stock','primary'),'stock');}
function settingsEditor(){openSheet('Stall settings',`<form id="settings-form"><div class="form-grid">${field('Stall name','stallName',C().stallName,'text','required maxlength="50"')}${field('Stall number','stallNumber',C().stallNumber,'text','required maxlength="8"')}${field('Event date','eventDate',C().eventDate,'date','required')}${field('Recovery target · ₹','target',C().target/100,'text','inputmode="decimal" required')}${field('Promo discount · ₹','promo',C().promo/100,'text','inputmode="decimal"')}${field('Promo minimum · ₹ (0 = none)','promoMinimum',C().promoMinimum/100,'text','inputmode="decimal"')}</div>${field('Current operator','operator',C().operator,'text','required maxlength="40"')}<div class="field"><label for="operators">Team operators · one per line</label><textarea id="operators" name="operators">${esc(C().operators.join('\n'))}</textarea></div><h3 style="margin-bottom:15px">Game entry fees</h3><div class="form-grid">${C().games.map(g=>field(esc(g.name)+' · ₹','game-'+g.id,g.fee/100,'text','inputmode="decimal"')).join('')}</div>${field('Brand yellow accent','accent',C().accent,'color')}<p class="footnote">Currency is INR. The recovery target already includes the agreed initial investment; don’t add the booking fee again.</p></form>`,btn('Save settings','save-settings','primary'),'settings');}
function expenses(){openSheet('Expense ledger',`<form id="expense-form" data-key="${uuid()}">${select('Category','category',['Ingredients','Packaging','Supplies','Other'],'Ingredients')}${field('Amount · ₹','amount','','text','inputmode="decimal" required')}${field('Description','description','','text','required maxlength="150"')}</form>${S().expenses.slice().reverse().map(e=>`<div class="receipt-line"><span>${esc(e.description)}<small>${esc(e.category)} · ${date(e.at)}</small></span><strong>${money(e.amount)}</strong></div>`).join('')}<p class="footnote">Expenses are shown separately from recovery. Only enter actual additional costs; avoid entering the same investment twice.</p>`,btn('Record expense','save-expense','primary'),'expenses');}
function backups(){openSheet('Keep a copy. Keep it safe.',`<div class="stack"><div class="notice">Sales live on this device. JSON includes both ledgers, catalog, settings and audit history. Keep a backup before clearing browser data or moving phones.</div>${btn('Download itemized orders CSV','export-csv','yellow')}${btn('Download payments CSV','export-payments','')}${btn('Download full JSON backup','export-json','primary')}<div class="separator"></div><div class="field"><label for="backup-file">Restore JSON backup · replaces this device’s data</label><input id="backup-file" type="file" accept="application/json,.json"></div>${btn('Validate & restore backup','import-backup','')}${btn('Reset practice ledger','reset-demo','')}${btn('Reset live event','reset-live','danger')}</div>`,btn('Done','close',''),'backups');}
function eventSetup(){const missing=C().products.filter(p=>p.active&&unitPrice(p,C())===null);openSheet('Ready for the big day?',`<div class="notice">${S().started?'Your live event has already started. This workflow will never erase existing sales.':'Check the menu, choose your cashier device, and start from your live ledger.'}</div><div class="separator"></div><div class="receipt-line"><span>Live orders</span><strong>${state.live.orders.length}</strong></div><div class="receipt-line"><span>Live collected</span><strong>${money(report(state.live,C()).collected)}</strong></div><h3 style="margin:20px 0 12px">Price checklist</h3>${missing.length?missing.map(p=>`<div class="admin-row"><div class="grow"><h3>${esc(p.name)}</h3><small>Set a price or hide this item</small></div>${btn('Set up','edit-product','small',`data-id="${p.id}"`)}</div>`).join(''):'<p class="notice">Every active item has a confirmed selling price.</p>'}<p class="footnote">Live mode starts empty on first launch. Practice records never mix with live records. If you already made live sales, starting the event preserves them.</p>`,btn('Start live event','start-live','primary',missing.length?'disabled':''),'event');}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const csvCell=x=>{let s=String(x??'');if(/^[=+@\-\t\r]/.test(s)&&typeof x!=='number')s="'"+s;return '"'+s.replaceAll('"','""')+'"';};
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');}
function exportCSV(payments=false){const rows=payments?[['Payment ID','Entity ID','Kind','Method','Amount INR','Timestamp IST'],...S().payments.map(p=>[p.id,p.entityId,p.kind,p.method,p.amount/100,date(p.at)])]:[['Order ID','Order number','Timestamp IST','Operator','Status','Payment','Product','Size','Flavour','Add-ons','Quantity','Unit INR','Line INR','Order subtotal INR','Order discount INR','Order total INR','Order net collected INR'],...S().orders.flatMap(o=>o.items.map(l=>[o.id,orderNo(o),date(o.at),o.operator,o.status,o.method,l.name,l.size,l.flavour,l.addons.map(a=>a.name).join(' + '),l.quantity,l.unitPrice/100,l.lineTotal/100,o.subtotal/100,o.discount/100,o.total/100,netFor(S(),o.id)/100]))];download(`packet-pataka-${state.mode}-${payments?'payments':'orders'}.csv`,csv(rows),'text/csv;charset=utf-8');toast('CSV exported. Order totals repeat on each item row.');}
function confirmReset(mode){openSheet(`Reset ${mode} ledger?`,`<form id="reset-form" data-mode="${mode}"><p class="notice danger">This permanently clears ${mode} orders, payments, games, expenses and milestones on this device. Export a JSON backup first.</p><div style="margin-top:20px">${field(`Type RESET ${mode.toUpperCase()} to confirm`,'confirmation','','text','autocomplete="off"')}</div></form>`,btn('Cancel','close','')+btn('Reset ledger','do-reset','danger'),'reset');}
async function handleAction(el){const a=el.dataset.action,id=el.dataset.id;
 if(a==='nav'){screen=el.dataset.screen;render();window.scrollTo(0,0);return;}
 if(a==='close'){closeSheet();return;}
 if(a==='sample-data'){await commit(st=>{if(st.mode!=='demo'||st.demo.orders.length||st.demo.draft.length)throw Error('Use an empty practice ledger and cart to load samples.');if(st.config.products.some(p=>p.active&&unitPrice(p,st.config)===null))throw Error('Set prices for the menu before loading practice sales.');for(const [id,quantity,method]of [['veggie-small',2,'UPI'],['corn-cheese-large',1,'Cash'],['fizz-sprite',3,'Cash']])createOrder(st.demo,st.config,{id:uuid(),items:[makeLine(st.config,id,{quantity})],method});addGame(st.demo,st.config,{id:uuid(),gameId:'wheel',method:'Cash'});});render();toast('Sample orders added to practice mode only.');return;}
 if(a==='category'){category=el.dataset.category;render();return;}
 if(a==='product'){const p=C().products.find(p=>p.id===id);if(p.custom)customize(id);else await addLine(makeLine(C(),id));return;}
 if(a==='custom-qty'){const e=document.querySelector('#custom-qty');e.textContent=Math.min(999,Math.max(1,Number(e.textContent)+Number(el.dataset.delta)));customPrice();return;}
 if(a==='add-custom'){const v=customValue();await addLine(makeLine(C(),v.id,v));closeSheet();return;}
 if(a==='qty'||a==='remove'){await commit(st=>{const s=st[st.mode],l=s.draft.find(l=>l.id===id);if(!l)return;if(a==='remove'||l.quantity+Number(el.dataset.delta)<=0)s.draft=s.draft.filter(l=>l.id!==id);else{l.quantity=Math.min(999,l.quantity+Number(el.dataset.delta));l.lineTotal=l.quantity*l.unitPrice;}if(!s.draft.length)s.draftId=uuid();});render();if(sheetKind==='cart')showCart();return;}
 if(a==='promo'||a==='checkout-promo'){await commit(st=>{st[st.mode].draftPromo=!st[st.mode].draftPromo;});promo=!!S().draftPromo;render();if(a==='checkout-promo')checkout();return;}
 if(a==='checkout'){checkout();return;}
 if(a==='view-cart'){showCart();return;}
 if(a==='complete'){await complete();return;}
 if(a==='filter'){orderFilter=el.dataset.filter;render();return;}
 if(a==='receipt'){receipt(id);return;}
 if(a==='pending-payment'){paymentSheet(id);return;}
 if(a==='mark-paid'){const f=document.querySelector('#pending-form'),d=new FormData(f);if(!d.has('confirmed'))throw Error('Confirm that payment was received.');await commit(st=>markPaid(st[st.mode],st.config,f.dataset.id,d.get('method')));closeSheet();render();toast('Payment recorded.');return;}
 if(a==='correction'){requireAdmin(()=>correctionSheet(id));return;}
 if(a==='save-correction'){const f=document.querySelector('#correction-form'),d=new FormData(f);if(!d.has('confirmed'))throw Error('Confirm the correction first.');await commit(st=>correctOrder(st[st.mode],st.config,f.dataset.id,{type:d.get('type'),amount:d.get('type')==='refund'?paise(d.get('amount')):0,reason:d.get('reason')}));closeSheet();render();toast('Correction recorded in the audit trail.');return;}
 if(a==='games'){closeSheet();screen='games';render();return;}
 if(a==='game-sheet'){gameSheet(id);return;}
 if(a==='save-game'){const f=document.querySelector('#game-form'),d=new FormData(f);const g=C().games.find(g=>g.id===f.dataset.id);if(g.fee&&!d.has('confirmed'))throw Error('Confirm the entry fee has been received.');await commit(st=>addGame(st[st.mode],st.config,{id:f.dataset.key,gameId:f.dataset.id,prize:d.get('prize'),method:d.get('method')||'Cash'}));closeSheet();render();toast('Game on! One play recorded.');return;}
 if(a==='game-reverse'){requireAdmin(()=>openSheet('Reverse game participation',`<form id="game-reverse-form" data-id="${id}">${field('Reason','reason','','text','required maxlength="200"')}${check('confirmed','I confirm this reversal and have returned any entry fee.')}</form>`,btn('Reverse play','do-game-reverse','danger')));return;}
 if(a==='do-game-reverse'){const f=document.querySelector('#game-reverse-form'),d=new FormData(f);if(!d.has('confirmed'))throw Error('Confirm this reversal.');await commit(st=>voidGame(st[st.mode],st.config,f.dataset.id,d.get('reason')));closeSheet();render();return;}
 if(a==='admin-menu'){requireAdmin(adminMenu);return;}
 if(a==='admin-stock'){requireAdmin(stockEditor);return;}
 if(a==='admin-settings'){requireAdmin(settingsEditor);return;}
 if(a==='expenses'){requireAdmin(expenses);return;}
 if(a==='backups'){backups();return;}
 if(a==='event-setup'){requireAdmin(eventSetup);return;}
 if(a==='edit-product'){productEditor(id);return;}
 if(a==='new-product'){productEditor();return;}
 if(a==='new-combo'){await commit(st=>st.config.products.push({id:uuid(),name:'New combo',category:'Combo Pataka',price:null,active:false,art:'packet',tint:'yellow',bundle:[{productId:'veggie-small',quantity:1}]}));productEditor(C().products.at(-1).id);return;}
 if(a==='save-product'){const f=document.querySelector('#product-form'),d=new FormData(f);if(!d.get('name').trim())throw Error('Give this product a name.');await commit(st=>{let p=st.config.products.find(p=>p.id===f.dataset.id);if(!p){p={id:f.dataset.id,tint:'cream',addons:[]};st.config.products.push(p);}const before=structuredClone(p);Object.assign(p,{name:d.get('name').trim(),category:d.get('category'),art:d.get('art'),active:d.has('active'),soldOut:d.has('soldOut')});if(p.base){p.base=d.get('base');p.size=p.base;p.stockKey=p.base;p.addons=d.getAll('addons');}else p.price=d.get('price')===''?null:paise(d.get('price'));if(p.bundle){p.bundle=st.config.products.filter(x=>x.stockKey&&!x.base&&!x.bundle).map(x=>({productId:x.id,quantity:integer(Number(d.get('bundle-'+x.id)))})).filter(x=>x.quantity);if(!p.bundle.length)throw Error('Choose at least one combo component.');}else if(!p.base){p.stockKey=d.get('stockKey');p.stockUnits=integer(Number(d.get('stockUnits')),1);}audit(st[st.mode],'product-updated',p.id,st.config.operator,{before,after:structuredClone(p)});});render();adminMenu();toast('Menu updated. Previous receipts are unchanged.');return;}
 if(a==='edit-addons'){addonsEditor();return;}
 if(a==='save-addons'){const d=new FormData(document.querySelector('#addons-form'));await commit(st=>{for(const x of st.config.addons){const name=d.get('name-'+x.id).trim();if(!name)throw Error('Add-on names cannot be empty.');x.name=name;x.price=paise(d.get('price-'+x.id));}if(d.get('newName').trim())st.config.addons.push({id:uuid(),name:d.get('newName').trim(),price:paise(d.get('newPrice'))});st.config.flavours=d.get('flavours').split('\n').map(s=>s.trim()).filter(Boolean);if(!st.config.flavours.length)throw Error('Keep at least one packet flavour.');audit(st[st.mode],'addons-updated','catalog',st.config.operator,{});});render();adminMenu();return;}
 if(a==='save-stock'){const d=new FormData(document.querySelector('#stock-form'));await commit(st=>{const used=stockUsed(st[st.mode]);for(const key of Object.keys(st.config.stock)){const n=integer(Number(d.get('stock-'+key)));if(n<(used[key]||0))throw Error(`${key} cannot be lower than stock already used.`);st.config.stock[key]=n;}st.config.inventory=d.has('inventory');audit(st[st.mode],'inventory-updated','stock',st.config.operator,{stock:structuredClone(st.config.stock)});});closeSheet();render();toast('Stock updated.');return;}
 if(a==='save-settings'){const d=new FormData(document.querySelector('#settings-form'));await commit(st=>{const before=structuredClone(st.config);for(const k of ['stallName','stallNumber','eventDate','operator']){if(!d.get(k)?.trim())throw Error('Complete the event details.');st.config[k]=d.get(k).trim();}for(const k of ['target','promo','promoMinimum'])st.config[k]=paise(d.get(k));if(st.config.target<=0)throw Error('Recovery target must be greater than zero.');st.config.operators=d.get('operators').split('\n').map(s=>s.trim()).filter(Boolean);st.config.accent=d.get('accent');for(const g of st.config.games)g.fee=paise(d.get('game-'+g.id));audit(st[st.mode],'settings-updated','settings',st.config.operator,{before,after:structuredClone(st.config)});refreshMilestones(st.live,st.config);refreshMilestones(st.demo,st.config);});closeSheet();render();toast('Stall settings saved.');return;}
 if(a==='save-expense'){const d=new FormData(document.querySelector('#expense-form'));const amount=paise(d.get('amount'));if(!amount||!d.get('description').trim())throw Error('Enter an amount and description.');await commit(st=>{const s=st[st.mode],key=document.querySelector('#expense-form').dataset.key;if(s.expenses.some(e=>e.id===key))return;const e={id:key,category:d.get('category'),amount,description:d.get('description').trim(),at:new Date().toISOString(),operator:st.config.operator};s.expenses.push(e);audit(s,'expense-recorded',e.id,st.config.operator,{amount});});render();expenses();toast('Expense recorded.');return;}
 if(a==='unlock'){const d=new FormData(document.querySelector('#pin-form')),pin=d.get('pin');if(!/^\d{4,8}$/.test(pin))throw Error('Use a 4–8 digit PIN.');if(state.pin){if(await hashPin(pin,state.pin.salt)!==state.pin.hash)throw Error('That PIN doesn’t match.');}else{if(pin!==d.get('repeat'))throw Error('The two PINs must match.');const salt=uuid(),hash=await hashPin(pin,salt);await commit(st=>{st.pin={salt,hash};});}adminUntil=Date.now()+600000;closeSheet();const fn=afterPin;afterPin=null;fn?.();render();return;}
 if(a==='admin-pin'){requireAdmin(()=>openSheet('Change admin PIN',`<form id="new-pin-form">${field('New 4–8 digit PIN','pin','','password','inputmode="numeric" maxlength="8"')}${field('Repeat new PIN','repeat','','password','inputmode="numeric" maxlength="8"')}</form>`,btn('Update PIN','change-pin','primary')));return;}
 if(a==='change-pin'){const d=new FormData(document.querySelector('#new-pin-form'));if(!/^\d{4,8}$/.test(d.get('pin'))||d.get('pin')!==d.get('repeat'))throw Error('Use matching 4–8 digit PINs.');const salt=uuid(),hash=await hashPin(d.get('pin'),salt);await commit(st=>{st.pin={salt,hash};});closeSheet();toast('Admin PIN updated.');return;}
 if(a==='lock-admin'){adminUntil=0;render();toast('Admin locked.');return;}
 if(a==='operator'){openSheet('Who’s on the counter?',`<form id="operator-form">${select('Operator','operator',C().operators,C().operator)}</form>`,btn('Use this operator','save-operator','primary'));return;}
 if(a==='save-operator'){const d=new FormData(document.querySelector('#operator-form'));await commit(st=>{st.config.operator=d.get('operator');});closeSheet();render();return;}
 if(a==='export-csv'||a==='export-payments'){exportCSV(a==='export-payments');return;}
 if(a==='export-json'){download(`packet-pataka-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2),'application/json');toast('Full backup downloaded.');return;}
 if(a==='import-backup'){const file=document.querySelector('#backup-file').files[0];if(!file)throw Error('Choose a JSON backup first.');if(file.size>20000000)throw Error('Backup is larger than 20 MB.');const restored=validateBackup(JSON.parse(await file.text()));requireAdmin(()=>{openSheet('Replace this device’s data?',`<p class="notice danger">Validated backup: ${restored.live.orders.length} live orders, ${restored.demo.orders.length} practice orders. Your current data will be replaced. Download a current backup first if needed.</p>${check('restoreConfirmed','I confirm replacing this device’s data.')}`,btn('Cancel','close','')+btn('Restore backup','do-restore','danger'));sheet.restoreData=restored;});return;}
 if(a==='do-restore'){if(!sheet.querySelector('[name="restoreConfirmed"]').checked)throw Error('Confirm the restore first.');const restored=sheet.restoreData;await commit(st=>Object.assign(st,restored));sheet.restoreData=null;adminUntil=0;promo=false;closeSheet();render();toast('Backup restored.');return;}
 if(a==='reset-live'||a==='reset-demo'){requireAdmin(()=>confirmReset(a==='reset-live'?'live':'demo'));return;}
 if(a==='do-reset'){const f=document.querySelector('#reset-form'),d=new FormData(f),mode=f.dataset.mode;if(d.get('confirmation')!==`RESET ${mode.toUpperCase()}`)throw Error('Type the confirmation exactly.');await commit(st=>{st[mode]=session();audit(st[mode],'ledger-reset',mode,st.config.operator,{});});promo=false;closeSheet();render();toast(`${mode} ledger reset.`);return;}
 if(a==='mode-demo'||a==='mode-live'){await commit(st=>{st.mode=a==='mode-demo'?'demo':'live';});promo=!!S().draftPromo;screen='sell';closeSheet();render();toast(state.mode==='demo'?'Practice mode. Live sales are untouched.':'Back to your live counter.');return;}
 if(a==='start-live'){await commit(st=>{if(st.config.products.some(p=>p.active&&unitPrice(p,st.config)===null))throw Error('Configure or hide every unpriced active product.');st.mode='live';st.live.started=true;audit(st.live,'event-started','event',st.config.operator,{});});promo=false;screen='sell';closeSheet();render();toast('Live event started. Let’s make some noise!');return;}
 if(a==='persist'){const result=await navigator.storage?.persist?.();toast(result?'Persistent storage granted. Keep exporting backups.':'Storage persistence was not granted. Export backups regularly.');return;}
 if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else openSheet('Take Pataka to the counter.',`<div class="stack"><p class="notice">Open this app in Chrome or Edge and choose “Install app” from the browser menu. On iPhone, use Safari → Share → Add to Home Screen.</p><p style="font-size:13px;line-height:1.8">Visit online once to cache the app. Keep using the same browser or installed app for your sales. A different browser has its own separate ledger.</p></div>`,btn('Got it','close','primary'));return;}
}
const protectedActions=new Set(['edit-product','new-product','new-combo','save-product','edit-addons','save-addons','save-stock','save-settings','save-expense','save-correction','do-game-reverse','change-pin','do-restore','do-reset','start-live']);
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();if(protectedActions.has(el.dataset.action)&&Date.now()>=adminUntil){requireAdmin(()=>toast('Admin unlocked. Reopen the action to continue.'));return;}try{await handleAction(el);}catch(err){error(err);}});
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('change',e=>{try{if(e.target.closest('#custom-form'))customPrice();if(e.target.closest('#checkout-form'))checkoutFields();}catch(err){error(err);}});
document.addEventListener('input',e=>{if(e.target.id==='order-search'){const cursor=e.target.selectionStart;search=e.target.value;render();const input=document.querySelector('#order-search');input.focus();input.setSelectionRange(cursor,cursor);}if(e.target.name==='cashReceived')checkoutFields();});
sheet.addEventListener('cancel',()=>{sheetKind='';});
window.addEventListener('online',render);window.addEventListener('offline',render);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key==='Enter'&&screen==='sell'&&!sheet.open){e.preventDefault();checkout();}});
onExternalChange(async()=>{state=await read();promo=!!S().draftPromo;render();if(sheet.open){closeSheet();toast('Another tab updated this device’s ledger. Please reopen your panel.');}});
try{state=await init();promo=!!S().draftPromo;render();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline cache could not be prepared. Keep this tab open.'));}}catch(e){app.innerHTML=`<div class="boot"><h1>Storage needs attention.</h1><p>Packet Pataka cannot safely save orders in this browser.</p><p>Use a regular browser window with IndexedDB enabled, then reload.</p></div>`;console.error(e);}
